{
  "primary_meaning": "Divine presence and glory of God (theophanic cloud / Shekinah)",
  "primary_basis": [
    "Exodus 13:21-22 (pillar of cloud)",
    "Exodus 19:9, 16; 24:15-18 (Sinai theophany)",
    "Exodus 40:34-38 (glory cloud over tabernacle)",
    "1 Kings 8:10-11 (cloud filling the temple)",
    "Matthew 17:5 (bright cloud at Transfiguration)",
    "Acts 1:9 (ascension in a cloud)",
    "Revelation 1:7; Daniel 7:13 (coming with/on the clouds)"
  ],
  "alternatives": [
    {
      "meaning": "Divine judgment, wrath, or storm theophany",
      "basis": [
        "Psalm 97:2",
        "Nahum 1:3",
        "Joel 2:2",
        "Zephaniah 1:15"
      ],
      "prominence": "common"
    },
    {
      "meaning": "A multitude or host of people (\"cloud of witnesses\")",
      "basis": [
        "Hebrews 12:1",
        "Isaiah 60:8 (occasional figurative use)"
      ],
      "prominence": "common"
    },
    {
      "meaning": "Concealment, hiddenness, or inaccessibility of God",
      "basis": [
        "Lamentations 3:44",
        "Job 22:14",
        "Psalm 18:11"
      ],
      "prominence": "minority"
    },
    {
      "meaning": "Emptiness or false promises (\"clouds without water\")",
      "basis": [
        "Jude 12",
        "2 Peter 2:17"
      ],
      "prominence": "rare"
    }
  ],
  "has_settled_consensus": true,
  "confidence": "high",
  "notes": "Across patristic, medieval, Reformation, and modern evangelical/biblical-studies sources the glory/presence cloud is the dominant and most consistently taught symbolic reading for \"cloud\" as a biblical symbol; other uses exist but are secondary or context-specific."
}
